import Foundation

// Exercise pictograms: equipment and movements, drawn in a 24 x 24 grid.
// Generated from the glyph kit (a small drawing DSL that also renders the
// review sheets), so edit the kit, not the drawing strings below.
//
// Each glyph is a list of drawing steps. Strokes are round-capped and
// round-joined; "clear" steps erase what's underneath, which gives the
// thin gaps that separate a near limb from the body behind it.

/// A point in the 24 x 24 glyph grid (y grows downward).
public struct GlyphPoint: Hashable, Sendable {
    public var x: Double
    public var y: Double
}

public enum GlyphOp: Hashable, Sendable {
    /// A polyline of the given width.
    case stroke([GlyphPoint], width: Double)
    /// Erases along a polyline of the given width.
    case clearStroke([GlyphPoint], width: Double)
    case fill([GlyphPoint])
    case clearFill([GlyphPoint])
    case disc(GlyphPoint, radius: Double)
    case clearDisc(GlyphPoint, radius: Double)
    /// x, y, width, height and corner radius.
    case roundedRect(x: Double, y: Double, width: Double, height: Double, radius: Double)
    case clearRoundedRect(x: Double, y: Double, width: Double, height: Double, radius: Double)
}

public enum ExerciseGlyph: String, CaseIterable, Hashable, Sendable {
    // Equipment
    case dumbbell, kettlebell, barbell, ezBar, trapBar, smithMachine, machine, cable, band, plate, landmine
    case medicineBall, stabilityBall, foamRoller, suspension, rings, sled, sandbag, jumpRope, battleRope
    case box, stone, log, tire, keg, yoke, sledgehammer, farmerHandles, abWheel, climbingRope, heavyBag
    case gripper, massageGun, slider
    // Movements
    case pushUp, plank, sidePlank, mountainClimber, handstand, planche, pullUp, hang, hangingLegRaise
    case invertedRow, frontLever, muscleUp, dip, benchDip, lSit, squat, pistolSquat, wallSit, lunge
    case lateralLunge, stepUp, calfRaise, nordicCurl, gluteBridge, hipThrust, hinge, crunch, sitUp, vUp
    case hollowHold, legRaise, deadBug, russianTwist, superman, birdDog, donkeyKick, sideLying, bearCrawl
    case burpee, jumpingJack, jump, boxJump, highKnees, buttKicks, run, stand, forwardFold, downwardDog
    case childsPose, cobra, catCow, lungeStretch, seatedStretch, kneeHug, quadStretch, sideStretch
    case calfStretch, legSwing, armCircles

    /// The drawing steps, parsed once.
    public var ops: [GlyphOp] { Self.parsed[self] ?? [] }

    /// Whether this glyph draws a person (rather than a piece of kit).
    public var isFigure: Bool { !Self.equipment.contains(self) }

    static let equipment: Set<ExerciseGlyph> = [
        .dumbbell, .kettlebell, .barbell, .ezBar, .trapBar, .smithMachine, .machine, .cable, .band,
        .plate, .landmine, .medicineBall, .stabilityBall, .foamRoller, .suspension, .rings, .sled,
        .sandbag, .jumpRope, .battleRope, .box, .stone, .log, .tire, .keg, .yoke, .sledgehammer,
        .farmerHandles, .abWheel, .climbingRope, .heavyBag, .gripper, .massageGun, .slider,
    ]

    private static let parsed: [ExerciseGlyph: [GlyphOp]] = Dictionary(
        uniqueKeysWithValues: allCases.map { ($0, parse($0.source)) }
    )

    /// "s w x,y x,y…" stroke, "S" erase stroke; "f x,y…" fill, "F" erase;
    /// "d r x,y" disc, "D" erase disc; "r x y w h radius" rounded rectangle,
    /// "R" erase rectangle. Steps are separated by ";".
    static func parse(_ text: String) -> [GlyphOp] {
        text.split(separator: ";").compactMap { step in
            let parts = step.split(separator: " ")
            guard let code = parts.first else { return nil }
            let values = parts.dropFirst()
            func point(_ token: Substring) -> GlyphPoint? {
                let xy = token.split(separator: ",")
                guard xy.count == 2, let x = Double(xy[0]), let y = Double(xy[1]) else { return nil }
                return GlyphPoint(x: x, y: y)
            }
            switch code {
            case "s", "S":
                guard let width = values.first.flatMap({ Double($0) }) else { return nil }
                let points = values.dropFirst().compactMap(point)
                return code == "s" ? .stroke(points, width: width) : .clearStroke(points, width: width)
            case "f", "F":
                let points = values.compactMap(point)
                return code == "f" ? .fill(points) : .clearFill(points)
            case "d", "D":
                guard values.count == 2, let radius = Double(values[values.startIndex]),
                      let center = point(values[values.index(after: values.startIndex)]) else { return nil }
                return code == "d" ? .disc(center, radius: radius) : .clearDisc(center, radius: radius)
            case "r", "R":
                let numbers = values.compactMap { Double($0) }
                guard numbers.count == 5 else { return nil }
                return code == "r"
                    ? .roundedRect(x: numbers[0], y: numbers[1], width: numbers[2], height: numbers[3], radius: numbers[4])
                    : .clearRoundedRect(x: numbers[0], y: numbers[1], width: numbers[2], height: numbers[3], radius: numbers[4])
            default:
                return nil
            }
        }
    }

